import type { JSX, ReactNode } from "react";
import type { FieldErrors, UseFormProps, UseFormReturn } from "react-hook-form";
import type { ZodSchema } from "zod";
import type { CardSelectProps } from "@/components/bevelui/controls/card-select";
import type { ChipSelectProps } from "@/components/bevelui/controls/chip-select";
import type { RatingFieldProps } from "@/components/bevelui/controls/rating-field";
import type { SelectFieldProps } from "@/components/bevelui/controls/select-field";
import type { TagInputProps } from "@/components/bevelui/controls/tag-input";
import type { Icon } from "@tabler/icons-react";

// ─── Form mode ────────────────────────────────────────────────────────────────

export type FormEngineMode = "multi-step" | "single";
export type FormEngineValidation = "per-step" | "on-submit";

// ─── Plugin system ────────────────────────────────────────────────────────────

/**
 * Plugins are the primary extension point for the form engine.
 *
 * @example — zod validation plugin (use the built-in helper)
 * plugins={[createZodPlugin(mySchema)]}
 *
 * @example — analytics plugin
 * plugins={[{
 *   name: "analytics",
 *   onStepChange: (step, values) => track("step_viewed", { step }),
 *   onSubmit: (values) => track("form_submitted"),
 * }]}
 */
export type FormEnginePlugin = {
  name: string;
  onMount?: (values: Record<string, unknown>) => void;
  onStepChange?: (step: number, values: Record<string, unknown>) => void;
  onFieldChange?: (
    field: string,
    value: unknown,
    values: Record<string, unknown>,
  ) => void;
  /**
   * Return false to block navigation away from this step.
   * Runs after react-hook-form per-step trigger passes.
   * Use this for async checks (username availability, server validation).
   */
  onValidate?: (
    step: number,
    values: Record<string, unknown>,
  ) => Promise<boolean> | boolean;
  onSubmit?: (values: Record<string, unknown>) => Promise<void>;
};

// ─── Field variants ───────────────────────────────────────────────────────────

export type TextInputProps = {
  icon?: Icon;
};

export type FormEngineFieldVariant =
  | { variant: "text"; props?: TextInputProps }
  | { variant: "number"; props?: TextInputProps }
  | { variant: "email"; props?: TextInputProps }
  | { variant: "password"; props?: TextInputProps }
  | { variant: "textarea"; props?: TextInputProps }
  | { variant: "checkbox"; props?: never }
  | { variant: "date"; props?: never }
  | { variant: "phone"; props?: never }
  | { variant: "select"; props?: SelectFieldProps }
  | { variant: "card-select"; props?: CardSelectProps }
  | { variant: "chip-select"; props?: ChipSelectProps }
  | { variant: "tag-input"; props?: TagInputProps }
  | { variant: "rating"; props?: RatingFieldProps }
  | { variant: "file"; props?: never };

// ─── Field definition ─────────────────────────────────────────────────────────

export type FormEngineFieldDef = {
  /** Must match a key in your form values */
  key: string;
  label?: string;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  className?: string;
  defaultValue?: unknown;
  /**
   * Conditionally show or hide this field.
   * Return true to show, false to hide.
   *
   * @example
   * showWhen: (values) => values.plan === "pro"
   */
  showWhen?: (values: Record<string, unknown>) => boolean;
} & FormEngineFieldVariant;

// ─── Step definition ──────────────────────────────────────────────────────────

export type FormEngineStepDef = {
  id: string;
  title?: string;
  description?: string;
  fields: FormEngineFieldDef[];
  /**
   * Custom layout — receives rendered fields and actions as JSX.
   *
   * @example
   * layout: (fields, actions) => (
   *   <div className="grid grid-cols-2 gap-8">
   *     <div>{fields}</div>
   *     <div className="mt-auto">{actions}</div>
   *   </div>
   * )
   */
  layout?: (fields: JSX.Element, actions: JSX.Element) => JSX.Element;
  /**
   * Async guard — called after validation passes.
   * Return false to block navigation (e.g. check username availability).
   */
  guard?: (values: Record<string, unknown>) => Promise<boolean> | boolean;
};

// ─── Config ───────────────────────────────────────────────────────────────────

export type FormEngineConfig = {
  id?: string;
  mode?: FormEngineMode;
  validation?: FormEngineValidation;
  resolver?: UseFormProps['resolver'];
  /**
   * Full-form Zod schema.
   * For per-step zod validation, use createZodPlugin() instead.
   */
  schema?: ZodSchema;
  steps: FormEngineStepDef[];
};

// ─── Field state ──────────────────────────────────────────────────────────────

export type FormEngineFieldState = {
  visible: boolean;
  disabled: boolean;
};

export type FormDefaultValues = Record<number, Record<string,unknown>>;

// ─── Context value ────────────────────────────────────────────────────────────

export type FormEngineContextValue = {
  /** The react-hook-form instance. Expose for advanced consumers. */
  form: UseFormReturn<Record<string, unknown>>;
  values: Record<string, unknown>;
  setFieldValue: (field: string, value: unknown) => void;

  currentStep: number;
  totalSteps: number;
  isFirstStep: boolean;
  isLastStep: boolean;
  goNext: () => Promise<void>;
  goBack: () => void;
  goTo: (step: number) => void;

  /** Computed visibility/disabled per field key */
  fieldState: Record<string, FormEngineFieldState>;

  isSubmitting: boolean;
  isValidating: boolean;
  errors: FieldErrors<Record<string, unknown>>;

  config: FormEngineConfig;
  defaultValues?: FormDefaultValues;
  plugins: FormEnginePlugin[];
};

// ─── Component props ──────────────────────────────────────────────────────────

export type FormEngineProps = {
  config: FormEngineConfig;
  defaultValues?: FormDefaultValues;
  plugins?: FormEnginePlugin[];
  onSubmit: (values: Record<string, unknown>) => Promise<void>;
  className?: string;
};

export type FormEngineRootProps = {
  config: FormEngineConfig;
  defaultValues?: FormDefaultValues;
  plugins?: FormEnginePlugin[];
  className?: string;
  children: ReactNode;
  onSubmit: (values: Record<string, unknown>) => Promise<void>;
};

import type { ZodSchema } from "zod";
import type { FormEngineConfig, FormEnginePlugin } from "./form-engine-types";
import { toast } from "sonner";

/**
 * Creates a per-step Zod validation plugin.
 *
 * Pass a map of step index → zod schema.
 * The plugin calls schema.safeParse() on the current step's values
 * and blocks navigation if it fails.
 *
 * @example
 * const validationPlugin = createZodPlugin({
 *   0: z.object({ name: z.string().min(2), email: z.string().email() }),
 *   1: z.object({ plan: z.enum(["free", "pro"]) }),
 * });
 *
 * <FormEngine config={config} plugins={[validationPlugin]} />
 */
export function createZodPlugin(
  schemas: Record<number, ZodSchema>,
): FormEnginePlugin {
  return {
    name: "zod-validation",
    async onValidate(step, values) {
      const schema = schemas[step];
      if (!schema) return true;
      const result = schema.safeParse(values);
      return result.success;
    },
  };
}

/**
 * Creates a logging plugin for development.
 * Logs every lifecycle event to the console.
 *
 * @example
 * plugins={[createLogPlugin()]}
 */
export function createLogPlugin(prefix = "[FormEngine]"): FormEnginePlugin {
  return {
    name: "logger",
    onMount: (v) => console.log(prefix, "mounted", v),
    onStepChange: (step, v) => console.log(prefix, `step ${step}`, v),
    onFieldChange: (field, value) =>
      console.log(prefix, `field "${field}" changed`, value),
    onValidate: async (step) => {
      console.log(prefix, `validating step ${step}`);
      return true;
    },
    onSubmit: async (v) => console.log(prefix, "submitted", v),
  };
}

/**
 * Creates an analytics plugin.
 * Pass your own track function.
 *
 * @example
 * plugins={[createAnalyticsPlugin((event, data) => mixpanel.track(event, data))]}
 */
export function createAnalyticsPlugin(
  track: (event: string, data?: Record<string, unknown>) => void,
): FormEnginePlugin {
  return {
    name: "analytics",
    onMount: () => track("form_started"),
    onStepChange: (step) => track("form_step_viewed", { step }),
    onSubmit: async () => track("form_submitted"),
  };
}

"use client";

import { createContext, useContext } from "react";
import type { FormEngineContextValue } from "./form-engine-types";

// ─── Context ──────────────────────────────────────────────────────────────────

export const FormEngineContext = createContext<FormEngineContextValue | null>(
  null,
);

// ─── Hook ─────────────────────────────────────────────────────────────────────

/**
 * useFormEngineContext — access the form engine state from any child component.
 * Must be used inside <FormEngine> or <FormEngineRoot>.
 */
export function useFormEngineContext(): FormEngineContextValue {
  const ctx = useContext(FormEngineContext);
  if (!ctx) {
    throw new Error(
      "useFormEngineContext must be used within <FormEngine> or <FormEngineRoot>",
    );
  }
  return ctx;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  useForm,
  type DefaultValues,
  type Path,
  type PathValue,
} from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import type {
  FormEngineConfig,
  FormEngineContextValue,
  FormEngineFieldState,
  FormEnginePlugin,
  FormEngineRootProps,
} from "./form-engine-types";

// ─── useFormEngineState ───────────────────────────────────────────────────────

export interface UseFormEngineStateProps extends Pick<
  FormEngineRootProps,
  "config" | "plugins" | "onSubmit" | "defaultValues"
> {
  config: FormEngineConfig;
  plugins?: FormEnginePlugin[];
}

/**
 * useFormEngineState — the core logic hook.
 * Returns everything that goes into FormEngineContext.
 * Internal use only — consumers use useFormEngineContext().
 */
export function useFormEngineState({
  config,
  defaultValues,
  plugins = [],
  onSubmit,
}: UseFormEngineStateProps): FormEngineContextValue {
  // ── Build initial values from step fields ─────────────────────────────────
  const initialValues = useMemo<Record<string, unknown>>(() => {
    const vals: Record<string, unknown> = {};
    config.steps.forEach((step,index) => {
      step.fields.forEach((field) => {
        vals[field.key] = field.defaultValue ?? defaultValues?.[index]?.[field.key];
      });
    });
    return vals;
  }, [config]);

  // ── react-hook-form ───────────────────────────────────────────────────────
  const form = useForm<Record<string, unknown>>({
    defaultValues: initialValues as DefaultValues<Record<string, unknown>>,
    resolver: config.resolver || config.schema ? zodResolver(config.schema as any) : undefined,
    mode: config.validation === "per-step" ? "onTouched" : "onSubmit",
  });

  const values = form.watch();
  const errors = form.formState.errors;
  const isSubmitting = form.formState.isSubmitting;

  // ── Step state ────────────────────────────────────────────────────────────
  const [currentStep, setCurrentStep] = useState(0);
  const [isValidating, setIsValidating] = useState(false);

  const allPlugins = useMemo(
    () => [...(plugins ?? []), ...plugins],
    [plugins, plugins],
  );

  // ── Mount hook ────────────────────────────────────────────────────────────
  const mounted = useRef(false);
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      allPlugins.forEach((p) => p.onMount?.(values));
    }
  }, []); // eslint-disable-line

  // ── Field state — visibility ──────────────────────────────────────────────
  const fieldState = useMemo<Record<string, FormEngineFieldState>>(() => {
    const state: Record<string, FormEngineFieldState> = {};
    config.steps.forEach((step) => {
      step.fields.forEach((field) => {
        const visible = field.showWhen ? field.showWhen(values) : true;
        state[field.key] = {
          visible,
          disabled: field.disabled ?? false,
        };
      });
    });
    return state;
  }, [values, config]);

  // ── setFieldValue ─────────────────────────────────────────────────────────
  const setFieldValue = useCallback(
    (field: string, value: unknown) => {
      form.setValue(
        field as Path<Record<string, unknown>>,
        value as PathValue<
          Record<string, unknown>,
          Path<Record<string, unknown>>
        >,
        { shouldDirty: true, shouldValidate: config.validation === "per-step" },
      );
      const next = form.getValues();
      allPlugins.forEach((p) => p.onFieldChange?.(field, value, next));
    },
    [form, allPlugins, config.validation],
  );

  // ── Navigation helpers ────────────────────────────────────────────────────
  const totalSteps = config.mode === "single" ? 1 : config.steps.length;
  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === totalSteps - 1;

  const goNext = useCallback(async () => {
    const step = config.steps[currentStep];
    setIsValidating(true);

    try {
      // 1. react-hook-form per-step field validation
      if (config.validation === "per-step") {
        const stepFields = step.fields.map(
          (f) => f.key as Path<Record<string, unknown>>,
        );
        const valid = await form.trigger(stepFields);
        if (!valid) return;
      }

      // 2. Step guard
      if (step.guard) {
        const passed = await step.guard(form.getValues());
        if (!passed) return;
      }

      // 3. Plugin validators (run in sequence — all must pass)
      for (const plugin of allPlugins) {
        if (plugin.onValidate) {
          const passed = await plugin.onValidate(currentStep, form.getValues());
          if (!passed) return;
        }
      }

      // 4. Submit on last step, advance on any other step
      if (isLastStep) {
        await form.handleSubmit(async (data) => {
          await onSubmit(data);
          for (const plugin of allPlugins) {
            await plugin.onSubmit?.(data);
          }
        })();
      } else {
        setCurrentStep((prev) => {
          const next = prev + 1;
          allPlugins.forEach((p) => p.onStepChange?.(next, form.getValues()));
          return next;
        });
      }
    } finally {
      setIsValidating(false);
    }
  }, [currentStep, isLastStep, config, allPlugins, form]);

  const goBack = useCallback(() => {
    setCurrentStep((prev) => {
      const next = Math.max(0, prev - 1);
      allPlugins.forEach((p) => p.onStepChange?.(next, form.getValues()));
      return next;
    });
  }, [allPlugins, form]);

  const goTo = useCallback(
    (step: number) => {
      const clamped = Math.max(0, Math.min(step, totalSteps - 1));
      setCurrentStep(clamped);
      allPlugins.forEach((p) => p.onStepChange?.(clamped, form.getValues()));
    },
    [allPlugins, form, totalSteps],
  );

  return {
    form,
    values,
    setFieldValue,
    currentStep,
    totalSteps,
    isFirstStep,
    isLastStep,
    goNext,
    goBack,
    goTo,
    fieldState,
    isSubmitting,
    isValidating,
    errors,
    config,
    plugins: allPlugins,
  };
}

"use client";

import { useController, type Path } from "react-hook-form";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupTextarea,
} from "@/components/ui/input-group";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Checkbox } from "@/components/ui/checkbox";
import { CardSelect } from "@/components/bevelui/controls/card-select";
import { ChipSelect } from "@/components/bevelui/controls/chip-select";
import { RatingField } from "@/components/bevelui/controls/rating-field";
import { SelectField } from "@/components/bevelui/controls/select-field";
import { TagInput } from "@/components/bevelui/controls/tag-input";
import { cn } from "@/lib/utils";
import { useFormEngineContext } from "./form-engine-context";
import type { FormEngineFieldDef } from "./form-engine-types";
import { DatePicker } from "../controls/date-picker";

// ─── useFormEngineField ───────────────────────────────────────────────────────

/**
 * useFormEngineField — read and write a single field from within the engine.
 * Integrates with react-hook-form for error messages.
 */
export function useFormEngineField(key: string) {
  const ctx = useFormEngineContext();

  const { field, fieldState } = useController({
    name: key as Path<Record<string, unknown>>,
    control: ctx.form.control,
  });

  return {
    value: field.value,
    onChange: (value: unknown) => {
      field.onChange(value);
      ctx.setFieldValue(key, value);
    },
    onBlur: field.onBlur,
    visible: ctx.fieldState[key]?.visible ?? true,
    disabled: ctx.fieldState[key]?.disabled ?? false,
    error: fieldState.error?.message,
  };
}

// ─── FormEngineField ──────────────────────────────────────────────────────────

interface FormEngineFieldProps {
  field: FormEngineFieldDef;
}

export function FormEngineField({ field }: FormEngineFieldProps) {
  const { value, onChange, onBlur, visible, disabled, error } =
    useFormEngineField(field.key);

  if (!visible) return null;

  const renderControl = () => {
    switch (field.variant) {
      case "text":
      case "email":
      case "number":
      case "password": {
        const Icon = field.props?.icon;
        return (
          <InputGroup>
            <InputGroupInput
              id={field.key}
              type={field.variant}
              value={(value as string) ?? ""}
              onChange={(e) => onChange(e.target.value)}
              onBlur={onBlur}
              placeholder={field.placeholder}
              disabled={disabled}
              aria-invalid={!!error}
            />
            {Icon && (
              <InputGroupAddon align="inline-end">
                <Icon className="size-4 text-muted-foreground" />
              </InputGroupAddon>
            )}
          </InputGroup>
        );
      }

      case "textarea": {
        const Icon = field.props?.icon;
        return (
          <InputGroup>
            <InputGroupTextarea
              value={(value as string) ?? ""}
              onChange={(e) => onChange(e.target.value)}
              onBlur={onBlur}
              placeholder={field.placeholder}
              disabled={disabled}
              aria-invalid={!!error}
            />
            {Icon && (
              <InputGroupAddon align="inline-end">
                <Icon className="size-4 text-muted-foreground" />
              </InputGroupAddon>
            )}
          </InputGroup>
        );
      }

      case "checkbox":
        return (
          <Checkbox
            id={field.key}
            checked={(value as boolean) ?? false}
            onCheckedChange={(checked) => onChange(checked)}
            disabled={disabled}
            aria-invalid={!!error}
          />
        );

      case "select":
        return (
          <SelectField
            {...(field.props ?? {})}
            options={field.props?.options ?? []}
            defaultValue={undefined}
            value={value as string}
            onChange={onChange}
            placeholder={field.placeholder}
          />
        );

      case "rating":
        return (
          <RatingField
            {...((field.props ?? {}) as any)}
            value={(value as number) ?? 0}
            onChange={(val) => onChange(val)}
            disabled={disabled}
          />
        );

      case "chip-select":
        return (
          <ChipSelect
            {...((field.props ?? {}) as any)}
            options={field.props?.options ?? []}
            value={value as string}
            onChange={(val) => onChange(val)}
            disabled={disabled}
          />
        );

      case "card-select":
        return (
          <CardSelect
            {...((field.props ?? {}) as any)}
            options={field.props?.options ?? []}
            value={value as string}
            onChange={(val) => onChange(val)}
            disabled={disabled}
          />
        );

      case "tag-input":
        return (
          <TagInput
            {...(field.props ?? {})}
            value={undefined}
            defaultValue={value as string[]}
            onChange={(val) => onChange(val)}
            disabled={disabled}
            placeholder={field.placeholder}
          />
        );

      case "date":
        return (
          <DatePicker
            {...((field.props ?? {}) as any)}
            // options={field.props ?? []}
            value={value as string}
            onChange={(val) => onChange(val)}
            disabled={disabled}
            withTime
          />
        );
      case "phone":
        return (
          <InputGroup>
            <InputGroupInput
              type={"tel"}
              value={(value as string) ?? ""}
              onChange={(e) => onChange(e.target.value)}
              onBlur={onBlur}
              placeholder={field.placeholder}
              disabled={disabled}
              aria-invalid={!!error}
            />
          </InputGroup>
        );

      case "file":
        return (
          <InputGroup>
            <InputGroupInput
              type="file"
              onChange={(e) => onChange(e.target.files)}
              disabled={disabled}
              aria-invalid={!!error}
            />
          </InputGroup>
        );

      default:
        return null;
    }
  };

  return (
    <Field
      orientation={field.variant == "checkbox" ? "horizontal" : "vertical"}
      className={cn(
        field.variant === "checkbox" && "flex-row-reverse",
        field.className,
      )}
    >
      {field.label && (
        <FieldLabel htmlFor={field.key}>
          {field.label}
          {field.required && (
            <span className="text-destructive ms-1" aria-hidden>
              *
            </span>
          )}
        </FieldLabel>
      )}
      {renderControl()}
      {/* Error message from react-hook-form / zod */}
      {error && <FieldError role="alert">{error}</FieldError>}
    </Field>
  );
}

FormEngineField.displayName = "FormEngineField";

"use client";

import { type ReactNode } from "react";
import { motion, AnimatePresence } from "motion/react";
import { cn } from "@/lib/utils";
import { useFormEngineContext } from "./form-engine-context";

// ─── Types ────────────────────────────────────────────────────────────────────

export type FormEngineProgressVariant = "dots" | "segments" | "numbers";
export type FormEngineProgressState = "active" | "inactive" | "completed";

export interface FormEngineProgressProps {
  className?: string;
  variant?: FormEngineProgressVariant;
  renderStep?: (index: number, state: FormEngineProgressState) => ReactNode;
}

// ─── Pill step ────────────────────────────────────────────────────────────────

interface PillStepProps {
  state: FormEngineProgressState;
  className?: string;
  onClick?: () => void;
}

const PILL_STATE = {
  active: { width: 24, backgroundColor: "bg-primary" },
  completed: { width: 6, backgroundColor: "bg-foreground" },
  inactive: { width: 6, backgroundColor: "bg-foreground/30" },
} as const;

export function FormEngineProgressPill({
  state,
  className,
  onClick,
}: PillStepProps) {
  const isActive = state === "active";

  return (
    <div
      onClick={onClick}
      className={cn(
        "relative py-4 flex items-center",
        onClick && "cursor-pointer",
        className,
      )}
    >
      <motion.div
        initial={false}
        animate={PILL_STATE[state]}
        transition={{ type: "spring", stiffness: 300, damping: 30 }}
        className={cn("h-1.5 rounded-full", PILL_STATE[state].backgroundColor)}
      />

      <AnimatePresence>
        {isActive && (
          <motion.div
            layoutId="pill-glow"
            className="absolute inset-0 bg-primary/40 blur-md rounded-full "
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          />
        )}
      </AnimatePresence>
    </div>
  );
}

// ─── FormEngineProgress ───────────────────────────────────────────────────────

export function FormEngineProgress({
  className,
  variant = "dots",
  renderStep,
}: FormEngineProgressProps) {
  const { currentStep, totalSteps, goTo } = useFormEngineContext();
  const steps = Array.from({ length: totalSteps });

  function getState(i: number): FormEngineProgressState {
    if (i === currentStep) return "active";
    if (i < currentStep) return "completed";
    return "inactive";
  }

  if (renderStep) {
    return (
      <div className={cn("flex items-center gap-2", className)}>
        {steps.map((_, i) => renderStep(i, getState(i)))}
      </div>
    );
  }

  if (variant === "dots") {
    return (
      <div className={cn("flex items-center justify-center gap-2", className)}>
        {steps.map((_, i) => (
          <FormEngineProgressPill
            key={i}
            state={getState(i)}
            onClick={() => goTo(i)}
          />
        ))}
      </div>
    );
  }

  return null;
}

FormEngineProgress.displayName = "FormEngineProgress";

"use client";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useFormEngineContext } from "./form-engine-context";

export interface FormEngineStepMetaProps {
  title?: string;
  description?: string;
  visual?: ReactNode;
  addons?: ReactNode;
  className?: string;
}

export function FormEngineStepMeta({
  title,
  description,
  visual,
  addons,
  className,
}: FormEngineStepMetaProps) {
  const { config, currentStep } = useFormEngineContext();
  const stepConfig = config.steps[currentStep];

  const resolvedTitle = title ?? stepConfig?.title;
  const resolvedDescription = description ?? stepConfig?.description;

  if (!resolvedTitle && !resolvedDescription && !visual && !addons) return null;

  return (
    <div
      className={cn(
        "flex flex-col gap-4",
        className,
      )}
    >
