export interface FormEngineNavigationProps {
  submitLabel?: string;
  nextLabel?: string;
  backLabel?: string;
  loadingLabel?: string;
  
  hideBackOnFirst?: boolean;
  className?: string;
  nextBtnClassName?: string;
  backBtnClassName?: string;
  nextIcon?: ReactNode;
  backIcon?: ReactNode;
  loadingIcon?: ReactNode;
  submitIcon?: ReactNode;
}

/**
 * FormEngineNavigation — minimal back/next/submit buttons.
 * For the full-featured version with layout presets and icon customisation,
 * use FormEngineActions instead.
 */
export function FormEngineNavigation({
  backLabel = "Back",
  nextLabel = "Continue",
  submitLabel = "Submit",
  backBtnClassName,
  nextBtnClassName,
  className,
}: FormEngineNavigationProps) {
  const {
    isFirstStep,
    isLastStep,
    isValidating,
    isSubmitting,
    goBack,
    goNext,
  } = useFormEngineContext();

  const busy = isValidating || isSubmitting;

  return (
    <div className={cn("flex items-center gap-3", className)}>
      {!isFirstStep && (
        <Button
          type="button"
          variant="outline"
          onClick={goBack}
          disabled={busy}
          className={cn("gap-2 cursor-pointer",backBtnClassName)}
        >
          <IconArrowLeft size={14} strokeWidth={2} />
          {backLabel}
        </Button>
      )}

      <Button
        type="button"
        onClick={goNext}
        disabled={busy}
        className={cn("ms-auto gap-2 cursor-pointer",nextBtnClassName)}
      >
        {busy && (
          <IconLoader2 size={14} strokeWidth={2} className="animate-spin" />
        )}
        {!busy && isLastStep && <IconCircleCheck size={14} strokeWidth={2.5} />}
        {isLastStep ? submitLabel : nextLabel}
        {!isLastStep && !busy && (
          <IconArrowRight size={14} strokeWidth={2} />
        )}
      </Button>
    </div>
  );
}

